# Track 7 Bagian D — PM-D1..D6 (quant toolkit analis portofolio)
LESSONS = [{'slug': 'pm-d1-data-harga', 'id': 'PM-D1', 'track': 'Portfolio Management', 'title_html': 'Data & Harga:<br/>Fondasi yang Jujur', 'title_plain': 'Data & Harga: Corporate Actions, Survivorship Bias, Cleaning', 'chapter_summary': 'Toolkit kuantitatif analis: harga adjusted vs unadjusted (split, dividen), survivorship bias, data cleaning (stale price, delisting), dan sinkronisasi frekuensi. Lab adjust split & demo survivorship bias.', 'tujuan': ['Menjelaskan mengapa harga harus di-adjust (split, dividen).', 'Menghitung penyesuaian corporate action.', 'Menjelaskan survivorship bias dan dampaknya.', 'Membersihkan data: stale price, delisting, missing.'], 'story_title': "Cerita: Saham yang 'Naik' 500% dalam Sehari", 'story': "<p><strong>2019</strong>: screener saham menampilkan <strong>XYZ +500%</strong> sehari! Junior analis berteriak <em>'breakout!'</em> — senior tersenyum: <strong>reverse split 1:5</strong>. Harga 'naik' 5x, nilai <strong>tetap</strong>. Yang beli di 'breakout' = <strong>tertipu data mentah</strong>.</p>\n<p>Twist-nya: <strong>80% 'anomali' di backtest</strong> = artefak data (split tak ter-adjust, saham delisted hilang, harga basi). <strong>Analisis canggih di atas data kotor = kebohongan presisi.</strong> Lesson ini: fondasi sebelum menara.</p>", 'concepts': [{'id': 'adjust', 'toc': 'Adjusted Price', 'title': 'Adjusted Price — Harga yang Jujur', 'body': '<p><strong>Definisi.</strong> <strong>Harga unadjusted</strong> = harga <em>tercatat</em> (menipu saat corporate action!). <strong>Adjusted</strong> = disesuaikan <em>mundur</em> untuk split &amp; dividen → <strong>return benar</strong>. <strong>Stock split</strong> 2:1: harga ÷2, jumlah saham ×2 (nilai tetap!). <strong>Dividen</strong>: harga turun ≈ dividen di ex-date → adjust <em>naik</em> histori.</p>\n<p><strong>Aturan</strong>: <em>selalu</em> pakai adjusted untuk return; unadjusted hanya untuk <em>level</em> (support/resistance).</p>', 'formulas': [{'math': 'P^{adj}_{t-1} = P_{t-1} \\times \\frac{P_t - D}{P_t} \\quad (dividen)', 'symbols': ['Split 2:1: semua harga sebelum split dibagi 2', 'Dividen Rp100, harga Rp1.000 → faktor 0,9', 'Return = dari harga ADJUSTED — bukan unadjusted!']}], 'intuisi': "Adjusted price seperti <strong>foto dengan koreksi inflasi</strong>: Rp1.000 tahun 2000 ≠ Rp1.000 kini. Split = <strong>pecah uang Rp100rb jadi 2×Rp50rb</strong> — 'harganya turun' tapi kantong sama. Data mentah = <strong>menukar pecahan dikira rugi</strong>.", 'kapan': 'Setiap perhitungan return, backtest, valuasi historis.', 'worked': {'title': '📐 Contoh: Jebakan XYZ (klik untuk buka)', 'body': "<p>XYZ: Rp10.000 → reverse split 1:5 → tercatat <strong>Rp50.000</strong> ('+400%'!).</p>\n<p><strong>Unadjusted</strong>: return +400% (salah!). <strong>Adjusted</strong>: harga lama ÷5 = Rp2.000 → Rp50.000... tunggu — reverse split: harga lama Rp10.000 ×5 = <strong>Rp50.000 adjusted</strong> → return <strong>0%</strong> ✓.</p>\n<p><strong>Screener</strong> tanpa adjust = daftar 'breakout' palsu. <strong>Selalu verifikasi corporate action</strong> sebelum euforia.</p>"}, 'charts': [{'data': '[{x: ["Jan","Feb","Mar","Apr","Mei"], y: [10000,10200,10100,50000,50500], type: "scatter", mode: "lines+markers", marker: {color: "#94a3b8"}, name: "unadjusted"}, {x: ["Jan","Feb","Mar","Apr","Mei"], y: [2000,2040,2020,10000,10100], type: "scatter", mode: "lines+markers", marker: {color: "#2a7de1"}, name: "adjusted (split 1:5 di Apr)"}]', 'title': 'Unadjusted vs adjusted: reverse split 1:5', 'layout': '{xaxis: {title: "Bulan"}, yaxis: {title: "Rp"}, showlegend: true}', 'cara': 'Abu = unadjusted (lompat); biru = adjusted (mulus).', 'interpretasi': 'Unadjusted <strong>melompat 5x</strong> di April — ilusi +400%. Adjusted <strong>mulus</strong>: return sebenarnya +1%. <strong>Setiap lompatan vertikal</strong> di chart = curigai corporate action dulu, rayakan kemudian.'}]}, {'id': 'survivor', 'toc': 'Survivorship Bias', 'title': 'Survivorship Bias — Kuburan yang Hilang', 'body': "<p><strong>Definisi.</strong> <strong>Survivorship bias</strong>: database hanya berisi saham <em>yang masih hidup</em> → return historis <strong>terlihat lebih tinggi</strong> (yang bangkrut 'dihapus'!). <strong>Dampak</strong>: bias <strong>2–4%/tahun</strong> untuk strategi saham!</p>\n<p><strong>Obat</strong>: database <em>point-in-time</em> (termasuk delisted), atau <strong>diskon mental</strong> hasil backtest.</p>", 'formulas': [], 'intuisi': "Survivorship bias seperti <strong>menilai sekolah dari alumninya yang sukses</strong> — yang DO tidak diundang reuni! 'Lulusan kami 90% sukses' = <strong>karena yang gagal tidak dihitung</strong>. Database saham = reuni tanpa yang bangkrut.", 'kapan': "Setiap backtest & studi 'anomali pasar'.", 'worked': {'title': "📐 Contoh: Strategi 'hebat' (klik untuk buka)", 'body': "<p>Backtest 2010–2020 saham IDX: return <strong>18%/tahun</strong>! Due diligence: database <em>tanpa</em> 40 saham delisted (mayoritas −100%).</p>\n<p><strong>Dengan delisted</strong>: return <strong>13%</strong>. Selisih <strong>5 poin = kuburan</strong>.</p>\n<p><strong>Aturan</strong>: tanya vendor data — 'apakah termasuk delisted?' Jika tidak → <strong>kurangi 2–4%</strong> dari hasil, atau <strong>tolak</strong>.</p>"}, 'charts': []}, {'id': 'cleaning', 'toc': 'Data Cleaning', 'title': 'Cleaning — Stale, Missing, Sinkron', 'body': "<p><strong>Definisi.</strong> <strong>Stale price</strong>: harga tidak bergerak berhari-hari (tidak likuid!) → volatilitas <em>understated</em>. <strong>Missing data</strong>: libur beda negara, suspensi. <strong>Sinkronisasi</strong>: pasar tutup beda jam (IDX vs NYSE!) → return 'harian' tidak sebanding.</p>\n<p><strong>Aturan</strong>: drop/flag stale &gt; 5 hari; forward-fill <em>hati-hati</em> (bukan untuk return!); samakan <em>timestamp</em> zona waktu.</p>", 'formulas': [], 'intuisi': 'Data kotor seperti <strong>bahan masakan basi</strong>: resep (model) Michelin pun menghasilkan <strong>keracunan</strong> (keputusan salah). 80% kerja analis = <strong>memilah bahan</strong>; 20% = memasak. Junior ingin langsung masak; senior <strong>cium dulu bahannya</strong>.', 'kapan': 'Sebelum analisis APAPUN: EDA + quality check dulu.', 'worked': {'title': '📐 Contoh: Stale price (klik untuk buka)', 'body': "<p>Saham gorengan: harga Rp500 <strong>tidak bergerak 20 hari</strong> → volatilitas terhitung <strong>2%</strong> ('aman!').</p>\n<p><strong>Realita</strong>: tidak ada transaksi (tidak likuid!) → saat ada, lompat <strong>±30%</strong> (ARB/ARA!). Vol '2%' = <strong>fatamorgana</strong>.</p>\n<p><strong>Check</strong>: hitung <strong>% hari nol-volume</strong>; jika &gt; 20% → <strong>exclude</strong> dari analisis risiko. Likuiditas = prasyarat statistik.</p>"}, 'charts': []}], 'myths': [{'t': 'Data dari vendor mahal = pasti bersih. Langsung analisis.', 'benar': '<strong>Tidak ada data bersih.</strong> Vendor pun punya stale, error split, missing delisted. <strong>Quality check</strong> (distribusi return, lompatan, stale) = ritual wajib <em>sebelum</em> analisis. Percaya tapi <strong>verifikasi</strong> — 30 menit EDA menghemat 3 bulan sesat.'}, {'t': 'Return dihitung dari harga penutupan biasa (unadjusted).', 'benar': 'Corporate action membuat unadjusted <strong>menipu</strong> (XYZ +400% palsu!). <strong>Selalu adjusted</strong> untuk return. Unadjusted hanya untuk level harga (chart pattern). Salah pilih = <strong>semua angka downstream salah</strong>.'}], 'tips': ['<strong>Ritual 3 cek sebelum analisis.</strong> (1) Plot harga — ada lompatan vertikal? (2) % hari stale/nol-volume. (3) Daftar corporate actions periode itu. 15 menit, selamatkan karir.', "<strong>Tanya 1 kalimat ke vendor data.</strong> 'Apakah database ini point-in-time termasuk delisted?' Jawabannya menentukan apakah backtest-mu <strong>fakta atau fiksi</strong>."], 'labs': [{'heading': 'Adjust Harga untuk Split', 'intro': 'Praktik menyesuaikan harga historis untuk stock split.', 'title': 'Lab 1 — Adjust Split', 'hint': 'Ubah RASIO 2 → 5 (split 1:5). Harga adjusted makin kecil — return tetap sama!', 'code': '# Adjust harga untuk stock split\nharga = [10000, 10200, 10100, 10300]  # sebelum split\nRASIO = 2          # split 2:1 (ubah! 5 = 1:5)\nharga_setelah = 5150  # tercatat setelah split\n\nadj = [h / RASIO for h in harga]\nret_unadj = (harga_setelah - harga[-1]) / harga[-1]\nret_adj = (harga_setelah - adj[-1]) / adj[-1]\n\nprint("Harga adjusted:", [f"{h:.0f}" for h in adj])\nprint(f"Return UNADJUSTED: {ret_unadj:.0%} (menipu!)")\nprint(f"Return ADJUSTED  : {ret_adj:.1%} (benar)")\nprint()\nprint("Split tidak menciptakan nilai - hanya pecah uang.")\n'}, {'heading': 'Demo Survivorship Bias', 'intro': 'Lihat bagaimana saham mati menggelembungkan return.', 'title': 'Lab 2 — Demo Survivorship', 'hint': 'Ubah MATI 40 → 0 (tanpa delisted). Bias hilang — itulah dunia fiksi database!', 'code': '# Survivorship bias: yang mati tidak tercatat\nimport random\nrandom.seed(42)\nHIDUP, MATI = 60, 40   # jumlah saham (ubah MATI!)\nret_hidup = [random.uniform(-0.2, 0.5) for _ in range(HIDUP)]\nret_mati = [-1.0] * MATI  # bangkrut = -100%\n\ntercatat = sum(ret_hidup) / HIDUP\nsebenarnya = (sum(ret_hidup) + sum(ret_mati)) / (HIDUP + MATI)\n\nprint(f"Return TERCATAT (tanpa yg mati): {tercatat:.1%}")\nprint(f"Return SEBENARNYA (semua)      : {sebenarnya:.1%}")\nprint(f"BIAS: {tercatat - sebenarnya:+.1%} (kuburan yang hilang!)")\nprint()\nprint("Database tanpa delisted = fiksi yang optimis.")\n'}], 'decisions': [{'kondisi': 'Hitung return/backtest', 'pakai': 'Harga adjusted', 'alasan': 'Corporate action menipu.', 'contoh': 'XYZ +400% palsu.'}, {'kondisi': 'Pilih database', 'pakai': 'Point-in-time + delisted', 'alasan': 'Bunuh survivorship bias.', 'contoh': 'Tanya vendor 1 kalimat.'}, {'kondisi': 'Saham tidak likuid', 'pakai': 'Flag/exclude (stale check)', 'alasan': 'Vol palsu.', 'contoh': '&gt;20% hari nol-volume.'}, {'kondisi': 'Pasar beda zona waktu', 'pakai': 'Sinkronkan timestamp', 'alasan': 'Return harian sebanding.', 'contoh': 'IDX vs NYSE.'}], 'rule10': '<ol><li><strong>Adjusted</strong> untuk return.</li><li><strong>Delisted</strong> termasuk.</li><li><strong>Stale</strong> di-flag.</li><li><strong>EDA dulu</strong>, model kemudian.</li></ol>', 'case': {'toc': 'Mini-Case: XYZ +500%', 'title': 'Breakout Palsu', 'body': "<p>Screener: XYZ +500% sehari. Junior: 'breakout!'. Faktanya: reverse split 1:5.</p>", 'q': '(a) Hitung return benar. (b) Sistem agar tidak terulang? (c) Pelajaran survivorship?', 'pembahasan': "<p>(a) <strong>0%</strong> (Rp10.000×5 = Rp50.000 adjusted). Bukan +400%.</p>\n<p>(b) <strong>Screener pakai adjusted</strong> + <strong>alert corporate action</strong> + <strong>ritual 3 cek</strong> (lompatan? stale? CA?). Junior dilatih <em>curiga dulu</em>.</p>\n<p>(c) <strong>Data mentah = musuh pertama.</strong> 80% 'anomali' = artefak. Bersihkan dulu, kagum kemudian.</p>"}, 'quiz': [{'q': 'Split 2:1, harga Rp10.000. Harga adjusted histori?', 'options': ['Rp10.000', 'Rp5.000', 'Rp20.000', 'Rp0'], 'correct': 1, 'why': 'Benar: bagi 2. Nilai tetap (saham ×2). Return dihitung dari adjusted!'}, {'q': 'Database tanpa delisted, backtest 18%. Realita kemungkinan?', 'options': ['18%', '13% (bias 2-5% dari kuburan)', '25%', '0%'], 'correct': 1, 'why': 'Benar: survivorship bias 2–4%/tahun. Tanya vendor: point-in-time?'}, {'q': 'Harga tidak bergerak 20 hari, vol 2%. Kesimpulan?', 'options': ['Aman', 'Stale price — vol fatamorgana, cek likuiditas', 'Beli', 'Jual'], 'correct': 1, 'why': 'Benar: tidak ada transaksi ≠ tidak ada risiko. % hari nol-volume &gt; 20% → exclude.'}, {'q': 'Dividen Rp100, harga Rp1.000 ex-date. Adjust histori?', 'options': ['Tidak usah', 'Kali 0,9 (turunkan histori)', 'Kali 1,1', 'Hapus'], 'correct': 1, 'why': 'Benar: harga ex-div turun ≈ dividen. Histori disesuaikan agar return kontinu.'}, {'q': 'Ritual wajib sebelum analisis?', 'options': ['Langsung model', 'Plot + cek lompatan/stale/CA (EDA)', 'Tanya AI', 'Copy template'], 'correct': 1, 'why': 'Benar: 15 menit EDA &gt; 3 bulan sesat. Data kotor = kebohongan presisi.'}], 'rangkum': ['<strong>Adjusted</strong>: untuk return (split/dividen disesuaikan mundur).', '<strong>Survivorship bias</strong>: 2–4%/tahun; butuh database point-in-time.', '<strong>Stale price</strong>: vol understated; flag &gt;20% hari nol-volume.', '<strong>Sinkronisasi</strong>: samakan timestamp antar-pasar.', '<strong>Ritual</strong>: plot, cek lompatan, daftar CA — sebelum model.', '<strong>Aturan</strong>: tidak ada data bersih; percaya tapi verifikasi.'], 'prev': ['pm-c11-ethics-esg', 'PM-C11'], 'next': ['pm-d2-optimisasi', 'PM-D2']}, {'slug': 'pm-d2-optimisasi', 'id': 'PM-D2', 'track': 'Portfolio Management', 'title_html': 'Optimisasi Portofolio:<br/>Black-Litterman & Robust', 'title_plain': 'Optimisasi: Mean-Variance, Black-Litterman, Risk Parity', 'chapter_summary': 'Optimisasi hands-on: mean-variance 3 aset (grid search), Black-Litterman (equilibrium + views), dan teknik robust (resampling, risk parity). Lab frontier 3-aset & kalkulator Black-Litterman sederhana.', 'tujuan': ['Menjalankan optimisasi mean-variance dengan grid search.', 'Menjelaskan intuisi Black-Litterman.', 'Menggabungkan market equilibrium dengan views.', 'Membedakan teknik robust: resampling, risk parity.'], 'story_title': "Cerita: Optimisasi yang 'Sempurna' dan Bangkrut", 'story': "<p><strong>1990-an</strong>: quant fund menjalankan mean-variance <em>murni</em>. Output: <strong>147% leverage di satu saham</strong> (E(R) tertinggi 0,3%!). <strong>1998</strong>: estimasi meleset sedikit → portofolio <strong>hancur</strong>. <strong>Error maximization</strong> (Michaud) memakan korban nyata.</p>\n<p>Twist-nya: <strong>matematikanya benar, inputnya sampah</strong> — dan optimisasi <em>memperkuat</em> sampah (bobot ekstrem di estimasi paling salah!). Solusinya bukan 'jangan optimisasi' — melainkan <strong>optimisasi yang rendah hati</strong>: Black-Litterman + constraints + resampling. Lesson ini: kekuatan dengan rem.</p>", 'concepts': [{'id': 'mv', 'toc': 'Mean-Variance Hands-On', 'title': 'Mean-Variance — Mesin dengan Rem', 'body': '<p><strong>Definisi.</strong> <strong>Mean-variance</strong>: pilih bobot max <em>Sharpe</em> (PM-C3). <strong>Grid search</strong>: coba ribuan kombinasi → frontier. <strong>Rem wajib</strong>: long-only, max 40%/aset, turnover limit.</p>\n<p><strong>Ingat PM-C4</strong>: tanpa constraints = <strong>error maximizer</strong>!</p>', 'formulas': [{'math': '\\max_w \\frac{w^T\\mu - r_f}{\\sqrt{w^T\\Sigma w}}', 'symbols': ['Max Sharpe (bukan max return!) — return per unit risiko', 'Constraints: <Tex math={String.raw`w_i \\geq 0`} />, <Tex math={String.raw`w_i \\leq 0{,}4`} />', 'Grid search: coba kombinasi kelipatan 10%']}], 'intuisi': 'Mean-variance seperti <strong>mesin balap</strong>: powerful, tapi tanpa rem (constraints) = <strong>tabrak tembok</strong> (147% satu saham!). Pembalap hebat = <strong>cepat + tahu kapan ngerem</strong>. Quant 1998 = gaspol tanpa rem.', 'kapan': 'Alokasi taktis; selalu dengan constraints + sensitivitas.', 'worked': {'title': '📐 Contoh: 3 aset (klik untuk buka)', 'body': '<p>Saham E(R) 10% σ18%; obligasi 7% σ6%; emas 5% σ15%; ρ saham-obligasi 0,2.</p>\n<p><strong>Grid search</strong> (kelipatan 10%, max 40%/aset): max Sharpe = <strong>30/40/30</strong> (Sharpe 0,62).</p>\n<p><strong>Tanpa max 40%</strong>: 60/40/0 (Sharpe 0,65) — <em>sedikit</em> lebih baik, <em>jauh</em> lebih rapuh. <strong>Robust &gt; optimal.</strong></p>'}, 'charts': [{'data': '[{x: [6,7,8,9.5,11,13,15,18], y: [0.35,0.45,0.52,0.58,0.62,0.6,0.55,0.5], type: "scatter", mode: "lines+markers", marker: {color: "#2a7de1"}, name: "frontier"}, {x: [9.5], y: [0.62], type: "scatter", mode: "markers", marker: {color: "#ef4444", size: 12}, name: "max Sharpe"}]', 'title': 'Frontier 3 aset: Sharpe vs volatilitas (ilustrasi)', 'layout': '{xaxis: {title: "Volatilitas (%)"}, yaxis: {title: "Sharpe ratio"}, showlegend: true}', 'cara': 'Kurva = Sharpe tiap titik frontier; titik merah = maksimum.', 'interpretasi': 'Sharpe <strong>naik lalu turun</strong>: titik optimal ≠ risiko maksimal. Max Sharpe (merah) = <strong>return per risiko terbaik</strong>. Titik di kanan = <em>return lebih tinggi, efisiensi lebih rendah</em> — pilih sesuai <strong>risk appetite IPS</strong>, bukan serakah.'}]}, {'id': 'bl', 'toc': 'Black-Litterman', 'title': 'Black-Litterman — Equilibrium + Views', 'body': "<p><strong>Definisi.</strong> <strong>BL</strong>: mulai dari <strong>equilibrium</strong> (market-cap weights → implied return) + campur <strong>views</strong> analis (dengan <em>confidence</em>!) → <strong>posterior return</strong> → optimisasi.</p>\n<p><strong>Keunggulan</strong>: intuitif (mulai dari 'pasar benar'), views <em>terukur</em> (bukan 0/100), bobot <strong>masuk akal</strong>.</p>", 'formulas': [{'math': '\\Pi = \\delta \\Sigma w_{mkt} \\quad;\\quad \\mu_{BL} = [(\\tau\\Sigma)^{-1} + P^T\\Omega^{-1}P]^{-1}[(\\tau\\Sigma)^{-1}\\Pi + P^T\\Omega^{-1}Q]', 'symbols': ['<Tex math={String.raw`\\Pi`} />: implied equilibrium return (dari bobot pasar!)', "<Tex math={String.raw`Q`} />: views analis (mis. 'saham &gt; obligasi 2%')", '<Tex math={String.raw`\\Omega`} />: confidence views (ragu → kecil pengaruhnya)', 'Hasil: antara pasar dan views, proporsional keyakinan']}], 'intuisi': "BL seperti <strong>musyawarah</strong>: pasar = <strong>pendapat mayoritas</strong> (equilibrium); analis = <strong>saksi ahli</strong> (views). Keputusan = <strong>mayoritas + ahli</strong>, dibobot <em>kredibilitas</em> (confidence). Bukan 'ahli selalu benar' (mean-variance murni) atau 'ahli diabaikan'.", 'kapan': 'Ada views house-analis yang ingin digabung sistematis.', 'worked': {'title': '📐 Contoh: View saham (klik untuk buka)', 'body': "<p>Equilibrium: saham 8%, obligasi 5%. View: <em>'saham outperform 3%'</em>, confidence <strong>sedang</strong>.</p>\n<p><strong>BL posterior</strong>: saham ≈ <strong>9%</strong>, obligasi ≈ 5% (bukan 8+3=11%! — di-<em>shrink</em> ke equilibrium).</p>\n<p><strong>Optimisasi</strong> → overweight saham <em>moderat</em> (+10%), bukan ekstrem. <strong>Views tanpa BL</strong> = 100% saham (bencana jika salah!).</p>"}, 'charts': []}, {'id': 'robust', 'toc': 'Teknik Robust', 'title': 'Robust — Rendah Hati', 'body': '<p><strong>Definisi.</strong> <strong>Resampling</strong> (Michaud): optimisasi di <em>banyak</em> simulasi input → rata-ratakan bobot (haluskan ekstrem!). <strong>Risk parity</strong> (PM-C4): bobot ∝ 1/σ. <strong>Max diversification</strong>: max rasio diversifikasi.</p>\n<p><strong>Prinsip</strong>: <strong>diversifikasi antar-model</strong> — tidak ada satu optimisasi yang dipercaya 100%.</p>', 'formulas': [], 'intuisi': 'Robust seperti <strong>tanya 100 dokter</strong> (resampling) vs 1 dokter (mean-variance tunggal). Satu dokter bisa salah fatal; <strong>konsensus 100</strong> = aman. Mahal? Ya. Lebih murah dari <strong>bangkrut</strong>.', 'kapan': 'Input sangat tidak pasti (EM, aset baru); governance konservatif.', 'worked': {'title': '📐 Contoh: Resampling (klik untuk buka)', 'body': '<p>Input: E(R) saham 10% ±3%. <strong>MV tunggal</strong>: 60% saham.</p>\n<p><strong>Resampling</strong> (1000 simulasi E(R) 7–13%): bobot rata-rata <strong>45%</strong> (kadang 20%, kadang 70%!).</p>\n<p><strong>Hasil</strong>: 45% — <strong>mengakui ketidakpastian</strong>. Jika E(R) sebenarnya 7%: MV tunggal rugi besar; resampled <strong>selamat</strong>. Kerendahan hati = <strong>asuransi model</strong>.</p>'}, 'charts': []}], 'myths': [{'t': 'Optimisasi memberi jawaban optimal — ikuti bobotnya persis.', 'benar': '<strong>Error maximization</strong>: garbage in → <em>amplified</em> garbage out (147% satu saham!). Bobot 2 desimal = <strong>presisi palsu</strong>. Pakai constraints + BL + resampling + <strong>round ke 5%</strong>. Optimisasi = <em>alat berpikir</em>.'}, {'t': 'Black-Litterman terlalu akademis, tidak praktis.', 'benar': 'Intuisi BL = <strong>musyawarah pasar + analis</strong> — justru <em>paling praktis</em>! Dipakai manajer institusi global. Implementasi sederhana (Lab 2) sudah menangkap 80% manfaat: <strong>views terukur + bobot masuk akal</strong>.'}], 'tips': ["<strong>Selalu tampilkan sensitivitas.</strong> 'Jika E(R) saham ±2%, bobot berubah X.' Jika berubah drastis = <strong>jangan percaya</strong> bobot itu. Analisis sensitivitas = kejujuran kuantitatif.", '<strong>Round bobot ke 5%.</strong> 32,47% → 30%. Presisi palsu menggoda overconfidence. Portofolio 30/40/30 yang dipahami &gt; 32,47/38,12/29,41 yang mistis.'], 'labs': [{'heading': 'Grid Search Frontier 3 Aset', 'intro': 'Cari portofolio max Sharpe dengan grid search + constraints.', 'title': 'Lab 1 — Grid Search', 'hint': 'Ubah MAX_W 0.4 → 1.0 (tanpa batas). Bobot ekstrem muncul — error maximization!', 'code': '# Grid search mean-variance 3 aset (pure Python)\nimport math, itertools\nER = [0.10, 0.07, 0.05]\nSIG = [0.18, 0.06, 0.15]\nRHO = [[1, 0.2, 0.1], [0.2, 1, 0.0], [0.1, 0.0, 1]]\nRF, MAX_W = 0.03, 0.4   # ubah MAX_W!\nCOV = [[RHO[i][j]*SIG[i]*SIG[j] for j in range(3)] for i in range(3)]\n\nterbaik = None\nfor w in itertools.product([i/10 for i in range(11)], repeat=3):\n    if abs(sum(w)-1) > 1e-9 or any(x > MAX_W + 1e-9 for x in w): continue\n    er = sum(a*b for a, b in zip(w, ER))\n    var = sum(w[i]*w[j]*COV[i][j] for i in range(3) for j in range(3))\n    sharpe = (er - RF)/math.sqrt(var)\n    if terbaik is None or sharpe > terbaik[0]: terbaik = (sharpe, w, er)\ns, w, er = terbaik\nprint(f"Max Sharpe {s:.2f}: saham {w[0]:.0%}, obligasi {w[1]:.0%}, emas {w[2]:.0%}")\nprint(f"E(R) {er:.1%}")\nprint("\\nTanpa MAX_W: bobot ekstrem (error maximization).")\nprint("Constraints = rem. Round ke 5%!")\n'}, {'heading': 'Kalkulator Black-Litterman Sederhana', 'intro': 'Gabungkan equilibrium + views dengan confidence.', 'title': 'Lab 2 — Black-Litterman', 'hint': 'Ubah CONF 0.5 → 0.9 (sangat yakin). Posterior mendekati views penuh!', 'code': '# Black-Litterman 2 aset (intuisi: rata-rata terbobot)\nEQ = {"saham": 0.08, "obligasi": 0.05}   # equilibrium (implied)\nVIEW = {"saham": 0.11, "obligasi": 0.05} # views analis\nCONF = 0.5   # confidence 0..1 (ubah!)\n\nprint(f"{\'aset\':<10}{\'equil\':>8}{\'view\':>8}{\'BL\':>8}")\nfor a in EQ:\n    bl = (1-CONF)*EQ[a] + CONF*VIEW[a]\n    print(f"{a:<10}{EQ[a]:>7.1%}{VIEW[a]:>8.1%}{bl:>8.1%}")\nprint()\nprint("CONF=0 -> ikut pasar. CONF=1 -> ikut analis.")\nprint("BL = musyawarah proporsional keyakinan.")\nprint("(Versi penuh pakai matriks kovarians; intuisi sama.)")\n'}], 'decisions': [{'kondisi': 'Alokasi dengan views analis', 'pakai': 'Black-Litterman', 'alasan': 'Sistematis + masuk akal.', 'contoh': 'Overweight moderat.'}, {'kondisi': 'Tidak percaya return forecast', 'pakai': 'Risk parity / min-variance', 'alasan': 'Hanya butuh kovarians.', 'contoh': 'Bobot ∝ 1/σ.'}, {'kondisi': 'Input sangat tidak pasti', 'pakai': 'Resampling', 'alasan': 'Rata-ratakan ketidakpastian.', 'contoh': '1000 simulasi.'}, {'kondisi': 'Bobot terlihat ekstrem', 'pakai': 'Curigai + tambah constraints', 'alasan': 'Error maximization.', 'contoh': 'Max 40%.'}], 'rule10': '<ol><li><strong>Constraints</strong> selalu.</li><li><strong>BL</strong> untuk views.</li><li><strong>Resampling</strong> untuk ketidakpastian.</li><li><strong>Round 5%</strong>.</li></ol>', 'case': {'toc': 'Mini-Case: 147% Satu Saham', 'title': 'Optimisasi Sempurna yang Bangkrut', 'body': '<p>Quant fund: MV murni → 147% satu saham (E(R) tertinggi 0,3%). Estimasi meleset → hancur 1998.</p>', 'q': '(a) Apa yang salah? (b) Bagaimana BL mencegah? (c) Aturan praktis?', 'pembahasan': '<p>(a) <strong>Error maximization</strong>: 0,3% = noise; optimisasi memperkuat noise jadi 147% leverage. Matematika benar, <strong>input sampah</strong>.</p>\n<p>(b) <strong>BL</strong>: mulai dari equilibrium (masuk akal) + views di-shrink by confidence → <strong>tidak ada</strong> bobot 147% dari view lemah.</p>\n<p>(c) <strong>Constraints + sensitivitas + round 5% + resampling.</strong> Optimisasi = alat berpikir, bukan mesin jawaban.</p>'}, 'quiz': [{'q': 'MV murni memberi 147% satu saham. Diagnosis?', 'options': ['Ikuti', 'Error maximization — tambah constraints', 'Leverage lagi', 'Ganti data'], 'correct': 1, 'why': 'Benar: optimisasi memperkuat error input. Constraints + BL + resampling = rem.'}, {'q': 'Intuisi Black-Litterman?', 'options': ['Ikuti analis 100%', 'Musyawarah: equilibrium pasar + views by confidence', 'Ikuti pasar 100%', 'Acak'], 'correct': 1, 'why': 'Benar: posterior = antara pasar dan views, proporsional keyakinan. Bobot masuk akal.'}, {'q': 'CONF=0 dalam BL artinya?', 'options': ['Ikuti analis', 'Ikuti equilibrium pasar', 'Error', 'Acak'], 'correct': 1, 'why': 'Benar: confidence nol → views diabaikan. CONF=1 → views penuh.'}, {'q': 'Resampling (Michaud) mengatasi?', 'options': ['Biaya', 'Ketidakpastian input (rata-ratakan banyak optimisasi)', 'Pajak', 'Likuiditas'], 'correct': 1, 'why': 'Benar: 1000 simulasi input → bobot rata-rata yang robust. Kerendahan hati kuantitatif.'}, {'q': 'Bobot 32,47%. Praktik terbaik?', 'options': ['Ikuti persis', 'Round ke 30% (presisi palsu)', 'Tambah desimal', 'Abaikan'], 'correct': 1, 'why': 'Benar: 2 desimal = presisi palsu dari input ±2%. Round 5% + pahami.'}], 'rangkum': ['<strong>MV</strong>: max Sharpe + constraints (rem wajib).', '<strong>Error maximization</strong>: garbage in → amplified garbage out.', '<strong>Black-Litterman</strong>: equilibrium + views × confidence.', '<strong>Robust</strong>: resampling, risk parity, max diversification.', '<strong>Aturan</strong>: sensitivitas selalu; round 5%; diversifikasi model.', '<strong>Prinsip</strong>: optimisasi rendah hati &gt; optimisasi sempurna.'], 'prev': ['pm-d1-data-harga', 'PM-D1'], 'next': ['pm-d3-regresi-faktor', 'PM-D3']}, {'slug': 'pm-d3-regresi-faktor', 'id': 'PM-D3', 'track': 'Portfolio Management', 'title_html': 'Regresi Faktor:<br/>Membedah Alpha', 'title_plain': 'Regresi Faktor: CAPM, Fama-French, Evaluasi Alpha', 'chapter_summary': 'Regresi untuk analis: CAPM (alpha, beta, t-stat), Fama-French 3 & 5 faktor, style analysis, dan uji signifikansi alpha (t > 2). Lab regresi CAPM OLS & penghitung t-stat alpha.', 'tujuan': ['Menjalankan regresi CAPM dan membaca outputnya.', 'Menjelaskan alpha, beta, R², t-statistik.', 'Menjelaskan faktor Fama-French.', 'Menguji klaim alpha dengan t-stat.'], 'story_title': "Cerita: Alpha 'Bintang' yang Ternyata Beta", 'story': "<p><strong>Manajer 'Bintang'</strong>: 5 tahun <strong>alpha +4%/tahun</strong>! Fee 2%. Investor antre. <strong>Analis</strong> menjalankan regresi Fama-French: <em>alpha</em> → <strong>+0,5% (t-stat 0,8)</strong>; <em>loading</em>: <strong>small-cap + value</strong> tinggi.</p>\n<p>Twist-nya: 'alpha' = <strong>beta tersamar</strong> (faktor small &amp; value yang sedang bagus!) — bisa direplikasi dengan <strong>ETF 0,2%</strong>. Investor membayar 2% untuk <strong>beta mahal</strong>. <strong>Regresi = kacamata X-ray</strong> klaim manajer. Lesson ini: membedah dengan angka.</p>", 'concepts': [{'id': 'capm', 'toc': 'Regresi CAPM', 'title': 'Regresi CAPM — Bedah Pertama', 'body': '<p><strong>Definisi.</strong> <strong>Regresi</strong>: R_p − R_f = α + β(R_m − R_f) + ε. <strong>Alpha</strong> (intersep): return <em>di luar</em> pasar — skill? <strong>Beta</strong> (slope): sensitivitas pasar. <strong>R²</strong>: % variasi dijelaskan pasar. <strong>t-stat</strong> = α/SE(α): <strong>|t| &gt; 2</strong> = signifikan!</p>\n<p><strong>Aturan</strong>: alpha tanpa t-stat = <strong>anecdote</strong>.</p>', 'formulas': [{'math': 'R_p - R_f = \\alpha + \\beta(R_m - R_f) + \\varepsilon', 'symbols': ['<Tex math={String.raw`\\alpha`} />: alpha (skill? atau noise?)', '<Tex math={String.raw`\\beta`} />: beta (eksposur pasar)', '<Tex math={String.raw`R^2`} />: 0,95 = closet indexer; 0,5 = aktif beneran', '<Tex math={String.raw`t = \\alpha/SE`} />: |t|&gt;2 = signifikan (95%)']}], 'intuisi': "Regresi CAPM seperti <strong>tes DNA</strong>: klaim 'saya unik' (alpha) diuji lab. Hasil: 80% 'unik' = <strong>DNA pasar</strong> (beta) + sedikit <strong>noise</strong>. Tes DNA tidak berbohong — <strong>marketing bisa</strong>.", 'kapan': 'Due diligence manajer APAPUN: regresi dulu, kagum kemudian.', 'worked': {'title': "📐 Contoh: Bedah 'Bintang' (klik untuk buka)", 'body': '<p>Return 5 tahun: alpha +4%, beta 1,1, R² 0,85, <strong>t-stat 1,2</strong>.</p>\n<p><strong>Verdict CAPM</strong>: t &lt; 2 → alpha <strong>tidak signifikan</strong> (bisa noise!). R² 0,85 → <strong>mirip pasar</strong>.</p>\n<p><strong>Fama-French</strong>: loading SMB +0,8, HML +0,6 → alpha sisa <strong>+0,5% (t 0,8)</strong>.</p>\n<p><strong>Kesimpulan</strong>: bayar 2% untuk <strong>beta small-value</strong> (ETF 0,2%!). <strong>Pecat atau nego.</strong></p>'}, 'charts': [{'data': '[{x: [-8,-5,-3,0,3,5,8,10], y: [-9,-5.5,-3,0.5,3.5,6,9,11.5], type: "scatter", mode: "markers", marker: {color: "#2a7de1"}, name: "return dana vs pasar"}, {x: [-8,10], y: [-8.8,11.6], type: "scatter", mode: "lines", line: {color: "#ef4444", width: 2}, name: "regresi (β=1,1, α=0,4)"}]', 'title': 'Regresi CAPM: slope = beta, intersep = alpha', 'layout': '{xaxis: {title: "Excess return pasar (%)"}, yaxis: {title: "Excess return dana (%)"}, showlegend: true}', 'cara': 'Titik = observasi bulanan; garis merah = regresi. Kemiringan = beta; perpotongan sumbu-y = alpha.', 'interpretasi': "Garis <strong>curam</strong> (β=1,1) = agresif vs pasar. Intersep <strong>kecil</strong> (α=0,4%) = 'skill' tipis. Titik <strong>mepet garis</strong> (R² tinggi) = tidak banyak <em>unik</em>. <strong>Regresi jujur</strong>: gambar ini &gt; 100 slide marketing."}]}, {'id': 'ff', 'toc': 'Fama-French', 'title': 'Fama-French — DNA Lebih Detail', 'body': '<p><strong>Definisi.</strong> <strong>FF3</strong>: pasar + <strong>SMB</strong> (small minus big) + <strong>HML</strong> (value minus growth). <strong>FF5</strong>: + <strong>RMW</strong> (profitabilitas) + <strong>CMA</strong> (investasi konservatif).</p>\n<p><strong>Gunanya</strong>: bedakan <strong>alpha murni</strong> dari <strong>premi faktor</strong> (yang bisa dibeli murah!).</p>', 'formulas': [{'math': 'R_p - R_f = \\alpha + \\beta_m MKT + \\beta_s SMB + \\beta_v HML + \\varepsilon', 'symbols': ['SMB, HML: premi faktor (PM-C8!) — bukan alpha', 'Alpha FF = setelah <em>semua</em> faktor dikontrol', 'Jika alpha hilang setelah FF → itu beta tersamar']}], 'intuisi': "FF seperti <strong>tes DNA lanjutan</strong>: CAPM = tes golongan darah (kasar); FF = <strong>sekuensing</strong> (detail). 'Unik' di tes kasar sering = <strong>keturunan umum</strong> di tes detail (small-value!).", 'kapan': "Manajer 'alpha' — selalu uji FF sebelum bayar mahal.", 'worked': {'title': '📐 Contoh: ETF vs manajer (klik untuk buka)', 'body': '<p>Manajer: fee 2%, alpha-FF +0,5% (t 0,8). Loading: SMB 0,8, HML 0,6.</p>\n<p><strong>Replikasi</strong>: 80% small-value ETF (0,2%) + 20% pasar → return <strong>sama</strong>, fee <strong>0,2%</strong>.</p>\n<p><strong>Hemat</strong>: 1,8%/tahun = <strong>Rp180jt per Rp10M</strong>. Regresi 10 menit = <strong>gaji analis setahun</strong>.</p>'}, 'charts': []}, {'id': 'style', 'toc': 'Style Analysis', 'title': 'Style Analysis — Cermin Gaya', 'body': "<p><strong>Definisi.</strong> <strong>Style analysis</strong> (Sharpe): regresi return dana ke <em>indeks gaya</em> (large/small × value/growth) dengan <strong>bobot ≥ 0, jumlah = 1</strong> → peta gaya + <strong>selection return</strong> (sisa = skill!).</p>\n<p><strong>Gunanya</strong>: 'manajer value' yang loading-nya <em>growth</em> = <strong>style drift</strong> (PM-C4!) — ketahuan!</p>", 'formulas': [], 'intuisi': "Style analysis seperti <strong>tes kepribadian</strong>: ngakunya 'value investor' (kata-kata), hasilnya 'growth chaser' (perbuatan). <strong>Perbuatan &gt; kata-kata</strong> — regresi membaca perbuatan.", 'kapan': 'Monitoring manajer: style konsisten dengan mandat?', 'worked': {'title': '📐 Contoh: Drift ketahuan (klik untuk buka)', 'body': "<p>Mandat: <em>large-value</em>. Style analysis: <strong>60% large-growth</strong>!</p>\n<p><strong>Konfrontasi</strong>: 'FOMO tech 2020?' Manajer: <em>'taktis...'</em> → <strong>style drift</strong> tanpa persetujuan.</p>\n<p><strong>Tindakan</strong>: peringatan tertulis / ganti. <strong>Mandat = kontrak</strong>; drift = pelanggaran. Regresi = <strong>polisi gaya</strong>.</p>"}, 'charts': []}], 'myths': [{'t': 'Alpha +4% = manajer hebat. Bayar 2% layak.', 'benar': '<strong>t-stat 1,2</strong> = tidak signifikan (noise!); setelah FF alpha <strong>+0,5%</strong> = beta small-value tersamar. <strong>Alpha tanpa t-stat = anecdote.</strong> Uji dulu: |t|&gt;2? FF? Jika tidak → <strong>ETF 0,2%</strong>.'}, {'t': 'R² tinggi = manajer bagus.', 'benar': '<strong>R² 0,95 = closet indexer</strong> — bayar fee aktif untuk hasil indeks! R² tinggi + alpha kecil = <strong>pecat</strong> (atau pindah ke pasif). R² <em>rendah</em> + alpha signifikan = <strong>aktif beneran</strong> (layak fee!).'}], 'tips': ['<strong>Selalu minta: alpha, t-stat, R², dan loadings FF.</strong> Empat angka ini = due diligence 80%. Manajer yang tidak bisa memberi = <strong>jawabannya</strong>.', '<strong>Curigai alpha dari periode pendek.</strong> t-stat ∝ √T — 1 tahun alpha +10% (t~1) = noise; 10 tahun +2% (t~2,5) = skill. <strong>Waktu = bukti.</strong>'], 'labs': [{'heading': 'Regresi CAPM (OLS Manual)', 'intro': 'Hitung alpha, beta, R², t-stat dari data return — tanpa library.', 'title': 'Lab 1 — Regresi CAPM', 'hint': 'Ubah ALPHA_TRUE 0.005 → 0.02 (skill beneran). t-stat naik > 2 — signifikan!', 'code': '# OLS manual: R_p - R_f = alpha + beta*(R_m - R_f)\nimport math, random\nrandom.seed(11)\nALPHA_TRUE, BETA_TRUE = 0.005, 1.1  # per bulan (ubah ALPHA!)\nN = 60\nrm = [random.uniform(-0.08, 0.08) for _ in range(N)]\nrp = [ALPHA_TRUE + BETA_TRUE*x + random.gauss(0, 0.03) for x in rm]\n\nmx, my = sum(rm)/N, sum(rp)/N\nbeta = sum((a-mx)*(b-my) for a, b in zip(rm, rp))/sum((a-mx)**2 for a in rm)\nalpha = my - beta*mx\nres = [b - (alpha + beta*a) for a, b in zip(rm, rp)]\nse = math.sqrt(sum(r*r for r in res)/(N-2))\nse_alpha = se*math.sqrt(1/N + mx**2/sum((a-mx)**2 for a in rm))\nr2 = 1 - sum(r*r for r in res)/sum((b-my)**2 for b in rp)\n\nprint(f"Alpha : {alpha:.3%} (t-stat {alpha/se_alpha:.1f})")\nprint(f"Beta  : {beta:.2f}")\nprint(f"R2    : {r2:.2f}")\nprint(f"|t|>2: {\'SIGNIFIKAN\' if abs(alpha/se_alpha) > 2 else \'tidak signifikan (noise?)\'}")\n'}, {'heading': 'Penghitung t-stat Alpha', 'intro': 'Seberapa lama track record dibutuhkan agar alpha signifikan?', 'title': 'Lab 2 — Kalkulator t-stat', 'hint': 'Ubah ALPHA 0.04 → 0.02. Butuh tahun LEBIH lama — alpha kecil butuh waktu!', 'code': '# t-stat alpha vs panjang track record: t = alpha*sqrt(T)/vol_aktif\nimport math\nALPHA = 0.04      # alpha tahunan (ubah!)\nTE = 0.08         # tracking error tahunan\n\nprint(f"{\'tahun\':>6}{\'t-stat\':>8}  signifikan?")\nfor T in [1, 3, 5, 10, 15]:\n    t = ALPHA*math.sqrt(T)/TE\n    print(f"{T:>6}{t:>8.1f}  {\'YA\' if t > 2 else \'belum\'}")\nprint()\nprint("t-stat tumbuh dengan AKAR waktu: butuh 4x lipat waktu")\nprint("untuk 2x keyakinan. Alpha kecil = butuh dekade!")\n'}], 'decisions': [{'kondisi': 'Due diligence manajer', 'pakai': 'Regresi CAPM + FF', 'alasan': 'Bedah klaim.', 'contoh': 'Alpha? t-stat?'}, {'kondisi': 'Alpha signifikan, R² rendah', 'pakai': 'Pertahankan (aktif beneran)', 'alasan': 'Skill unik.', 'contoh': 'Fee layak.'}, {'kondisi': 'Alpha tidak signifikan / beta tersamar', 'pakai': 'Ganti ETF / nego fee', 'alasan': 'Beta mahal.', 'contoh': 'Replikasi 0,2%.'}, {'kondisi': 'Monitoring gaya', 'pakai': 'Style analysis berkala', 'alasan': 'Deteksi drift.', 'contoh': 'Kuartalan.'}], 'rule10': '<ol><li><strong>Regresi dulu</strong>, kagum kemudian.</li><li><strong>|t| &gt; 2</strong> atau anecdote.</li><li><strong>FF</strong> untuk beta tersamar.</li><li><strong>R² tinggi</strong> = closet indexer.</li></ol>', 'case': {'toc': 'Mini-Case: Bintang Palsu', 'title': 'Alpha +4% yang Ternyata Beta', 'body': "<p>Manajer 'Bintang': alpha +4%, fee 2%. Regresi FF: alpha +0,5% (t 0,8), loading SMB/HML tinggi.</p>", 'q': '(a) Verdict? (b) Alternatif? (c) Sistem pencegahan?', 'pembahasan': '<p>(a) <strong>Beta tersamar</strong>: alpha tidak signifikan, premi faktor small-value. <strong>Tidak layak fee 2%.</strong></p>\n<p>(b) <strong>Replikasi ETF</strong> (0,2%): hemat 1,8%/tahun. Atau <strong>nego fee</strong> ke 0,5%.</p>\n<p>(c) <strong>Regresi wajib</strong> sebelum hire + <strong>style analysis kuartalan</strong> + <strong>aturan t-stat</strong> di IPS manajer.</p>'}, 'quiz': [{'q': 'Alpha +4%, t-stat 1,2. Kesimpulan?', 'options': ['Hebat', 'Tidak signifikan — bisa noise', 'Lumayan', 'Beli'], 'correct': 1, 'why': 'Benar: |t|&lt;2 = tidak signifikan 95%. Alpha tanpa t-stat = anecdote.'}, {'q': 'R² = 0,95, alpha kecil, fee 1,5%. Ini?', 'options': ['Aktif beneran', 'Closet indexer — pindah ke pasif', 'Hebat', 'Tahan'], 'correct': 1, 'why': 'Benar: mirip indeks tapi fee aktif = bayar mahal untuk beta. Pecat/pasifkan.'}, {'q': 'Setelah FF, alpha +4% → +0,5%. Artinya?', 'options': ['Alpha murni', 'Beta tersamar (premi faktor small-value)', 'Error', 'Beruntung'], 'correct': 1, 'why': "Benar: 'skill' = loading faktor yang bisa dibeli via ETF 0,2%."}, {'q': 't-stat tumbuh dengan?', 'options': ['Linear waktu', 'Akar waktu (butuh 4x waktu untuk 2x keyakinan)', 'Tidak tumbuh', 'Kuadrat'], 'correct': 1, 'why': 'Benar: t = α√T/TE. Alpha kecil butuh dekade untuk signifikan. Waktu = bukti.'}, {'q': 'Style analysis: mandat large-value, hasil 60% large-growth. Ini?', 'options': ['OK', 'Style drift — pelanggaran mandat', 'Taktis', 'Biarkan'], 'correct': 1, 'why': 'Benar: perbuatan ≠ kata-kata. Drift tanpa persetujuan = pelanggaran kontrak.'}], 'rangkum': ['<strong>CAPM</strong>: alpha (intersep), beta (slope), R², t-stat.', '<strong>|t| &gt; 2</strong> = signifikan; tanpa itu = anecdote.', '<strong>FF3/5</strong>: bedakan alpha murni vs premi faktor.', '<strong>Style analysis</strong>: peta gaya + deteksi drift.', '<strong>Closet indexer</strong>: R² tinggi + fee aktif = pecat.', '<strong>Aturan</strong>: regresi dulu, kagum kemudian; waktu = bukti.'], 'prev': ['pm-d2-optimisasi', 'PM-D2'], 'next': ['pm-d4-backtesting', 'PM-D4']}, {'slug': 'pm-d4-backtesting', 'id': 'PM-D4', 'track': 'Portfolio Management', 'title_html': 'Backtesting:<br/>Jangan Bohongi Diri', 'title_plain': 'Backtesting: Lookahead Bias, Overfitting, Walk-Forward', 'chapter_summary': 'Backtest yang jujur: lookahead bias, survivorship & biaya transaksi, overfitting (in-sample vs out-of-sample), walk-forward analysis, dan deflated Sharpe. Lab demo lookahead bias & walk-forward sederhana.', 'tujuan': ['Menjelaskan 3 dosa backtest: lookahead, survivorship, biaya.', 'Menjelaskan overfitting dan cara mendeteksinya.', 'Menjalankan walk-forward analysis.', 'Menghitung deflated Sharpe ratio.'], 'story_title': "Cerita: Strategi 'Sempurna' yang Hancur Live", 'story': "<p><strong>Quant</strong> menemukan strategi: backtest 10 tahun <strong>Sharpe 3,0</strong>! Live trading <strong>6 bulan</strong>: <strong>−20%</strong>. Audit: strategi memakai <strong>data laporan keuangan</strong> yang <em>dirilis 2 bulan setelah</em> periode trading — <strong>lookahead bias</strong> (melihat masa depan!).</p>\n<p>Twist-nya: <strong>backtest tidak berbohong — quant-nya yang bertanya salah</strong>. 'Bagaimana jika saya tahu masa depan?' = pertanyaan yang <em>selalu</em> dijawab 'cuan!'. <strong>Backtest jujur = pertanyaan jujur.</strong> Lesson ini: interogasi strategi sebelum pasar menginterogasi Anda.</p>", 'concepts': [{'id': 'dosa', 'toc': '3 Dosa Backtest', 'title': '3 Dosa — Lookahead, Survivorship, Biaya', 'body': '<p><strong>Definisi.</strong> <strong>Lookahead bias</strong>: pakai info <em>belum tersedia</em> saat itu (laporan keuangan, revisi data!). <strong>Survivorship</strong> (PM-D1): tanpa delisted. <strong>Biaya</strong>: tanpa komisi + <em>market impact</em> (PM-C10!).</p>\n<p><strong>Aturan</strong>: <em>point-in-time</em> data + <em>delisted</em> + <em>biaya realistis</em> — atau <strong>jangan backtest</strong>.</p>', 'formulas': [], 'intuisi': 'Lookahead bias seperti <strong>ujian dengan kunci jawaban</strong>: nilai 100! Tapi <strong>ujian sesungguhnya</strong> (live) tanpa kunci = gagal. Backtest dengan lookahead = <strong>latihan soal yang sudah tahu jawabannya</strong> — pede palsu.', 'kapan': "Setiap backtest: audit 'apakah info ini tersedia saat itu?'", 'worked': {'title': '📐 Contoh: Audit quant (klik untuk buka)', 'body': "<p>Strategi: beli setelah <em>'laba naik'</em>. Data: laporan tahunan <strong>final</strong> (revisi!).</p>\n<p><strong>Masalah</strong>: laporan final tersedia <strong>Mei</strong>; strategi 'trading' di <strong>Januari</strong> — <strong>melihat 4 bulan ke depan</strong>!</p>\n<p><strong>Perbaikan</strong>: pakai <em>vintage data</em> (as-reported saat itu) → Sharpe <strong>3,0 → 0,4</strong>. <strong>Strategi mati.</strong> Lebih baik mati di lab daripada <strong>di pasar dengan uang beneran</strong>.</p>"}, 'charts': []}, {'id': 'overfit', 'toc': 'Overfitting', 'title': 'Overfitting — Menghafal, Bukan Belajar', 'body': '<p><strong>Definisi.</strong> <strong>Overfitting</strong>: strategi <em>menghafal</em> noise historis (banyak parameter!) → <strong>in-sample bagus, out-of-sample hancur</strong>. <strong>Deteksi</strong>: <em>train/test split</em> waktu, <strong>walk-forward</strong>, <strong>deflated Sharpe</strong> (koreksi <em>jumlah trial</em>!).</p>\n<p><strong>Aturan</strong>: <strong>parameter sedikit</strong> + <strong>logika ekonomi</strong> + <strong>out-of-sample wajib</strong>.</p>', 'formulas': [{'math': 'DSR = \\Phi\\left(\\frac{(\\hat{SR} - SR_0)\\sqrt{T-1}}{\\sqrt{1 - \\gamma_3\\hat{SR} + \\frac{\\gamma_4-1}{4}\\hat{SR}^2}}\\right)', 'symbols': ['DSR: probabilitas Sharpe benar &gt; 0 setelah koreksi trial', '<Tex math={String.raw`SR_0`} />: ekspektasi Sharpe di bawah null (naik dengan JUMLAH TRIAL!)', "1000 trial → SR_0 ≈ 1,5 (bukan 0!): 'temuan' harus kalahkan itu", 'Praktis: makin banyak dicoba, makin skeptis']}], 'intuisi': 'Overfitting seperti <strong>murid menghafal kunci</strong> (in-sample 100!) tapi <strong>gagal ujian beda soal</strong> (out-of-sample). Walk-forward = <strong>ujian susulan berkala</strong>. Deflated Sharpe = <strong>guru yang tahu</strong> murid sudah intip 1000 kunci.', 'kapan': 'Setiap strategi: lapor in-sample DAN out-of-sample + jumlah trial.', 'worked': {'title': '📐 Contoh: 1000 trial (klik untuk buka)', 'body': "<p>Quant coba <strong>1000</strong> kombinasi parameter → terbaik Sharpe <strong>2,0</strong>!</p>\n<p><strong>Deflated</strong>: SR_0 (1000 trial) ≈ 1,5 → DSR = <strong>60%</strong> (tidak meyakinkan!).</p>\n<p><strong>Walk-forward</strong>: 2015–2018 train → 2019 test: Sharpe <strong>0,3</strong>. <strong>Mati.</strong></p>\n<p><strong>Pelajaran</strong>: 'terbaik dari 1000' = <strong>juara menghafal</strong>. Lapor <em>semua</em> trial, bukan juaranya.</p>"}, 'charts': [{'data': '[{x: ["2015","2016","2017","2018","2019","2020"], y: [2.5,2.8,3.0,2.7,0.3,0.1], type: "bar", marker: {color: ["#2a7de1","#2a7de1","#2a7de1","#2a7de1","#ef4444","#ef4444"]}, text: ["IS","IS","IS","IS","OOS","OOS"], textposition: "outside"}]', 'title': 'Sharpe in-sample vs out-of-sample: tanda overfitting', 'layout': '{xaxis: {title: "Tahun"}, yaxis: {title: "Sharpe"}, showlegend: false}', 'cara': 'Biru = in-sample (training); merah = out-of-sample (test).', 'interpretasi': '<strong>Jurang</strong> IS→OOS (3,0 → 0,3) = <strong>overfitting klasik</strong>: menghafal, bukan belajar. Strategi sehat: OOS <strong>mendekati</strong> IS (mis. 1,2 → 0,9). <strong>Tidak ada OOS = tidak ada strategi</strong> — hanya cerita.'}]}, {'id': 'wf', 'toc': 'Walk-Forward', 'title': 'Walk-Forward — Ujian Jujur', 'body': '<p><strong>Definisi.</strong> <strong>Walk-forward</strong>: train [2015–2017] → test 2018; <em>geser</em>: train [2016–2018] → test 2019; ... → rangkai <strong>out-of-sample murni</strong>. <strong>Anchored</strong> vs <strong>rolling</strong> window.</p>\n<p><strong>Keunggulan</strong>: mensimulasikan <em>penggunaan nyata</em> (re-estimasi berkala) + <strong>deteksi decay</strong> (strategi memburuk?).</p>', 'formulas': [], 'intuisi': "Walk-forward seperti <strong>simulasi musim</strong>: latih tim 3 tahun → tanding 1 tahun → <em>evaluasi</em> → latih lagi. Bukan 'latih 10 tahun lalu klaim juara selamanya'. <strong>Pasar berubah; strategi harus diuji berubah.</strong>", 'kapan': 'Validasi final sebelum live; monitoring decay setelah live.', 'worked': {'title': '📐 Contoh: Decay ketahuan (klik untuk buka)', 'body': '<p>Walk-forward 5 window: OOS Sharpe <strong>1,5 → 1,2 → 0,8 → 0,4 → 0,1</strong>.</p>\n<p><strong>Decay!</strong> — edge terkikis (crowding? regime berubah?).</p>\n<p><strong>Keputusan</strong>: <strong>jangan live</strong> (atau ukuran kecil + stop-loss edge). Walk-forward = <strong>detektor kematian dini</strong>. Strategi yang sekarat di OOS = <strong>jangan dihidupkan</strong> dengan uang.</p>'}, 'charts': []}], 'myths': [{'t': 'Backtest Sharpe 3,0 = strategi hebat. Langsung live.', 'benar': '<strong>1000 trial → ekspektasi 1,5</strong> (deflated!); lookahead bisa bikin 3,0 dari nol. <strong>Audit dulu</strong>: point-in-time? delisted? biaya? OOS? <strong>Backtest hebat + audit gagal = bom.</strong>'}, {'t': 'In-sample bagus = cukup. Out-of-sample buang-buang data.', 'benar': "<strong>In-sample = murid menghafal.</strong> Tanpa OOS/walk-forward = tidak ada bukti belajar. 'Buang data' untuk OOS = <strong>premi asuransi</strong> termurah. Strategi tanpa OOS = <strong>cerita, bukan strategi</strong>."}], 'tips': ["<strong>Catat SEMUA trial, bukan juaranya.</strong> Jumlah trial menentukan deflated Sharpe. 'Lupa' 999 trial gagal = <strong>penipuan diri</strong> (p-hacking). Jurnal trial = kejujuran kuantitatif.", '<strong>Asumsikan biaya 2x perkiraan.</strong> Komisi + spread + impact + slippage. Jika strategi mati dengan biaya 2x = <strong>terlalu rapuh untuk live</strong>. Margin of safety untuk backtest.'], 'labs': [{'heading': 'Demo Lookahead Bias', 'intro': "Buktikan bagaimana 'melihat masa depan' menciptakan Sharpe palsu.", 'title': 'Lab 1 — Demo Lookahead', 'hint': 'Ubah LOOKAHEAD True → False (jujur). Sharpe anjlok — itulah harga kejujuran!', 'code': '# Lookahead bias: trading dengan info masa depan vs jujur\nimport random\nrandom.seed(99)\nLOOKAHEAD = True   # ubah ke False!\nN = 120\nharga = [100.0]\nfor _ in range(N):\n    harga.append(harga[-1]*(1 + random.gauss(0.005, 0.03)))\n\ncuan = 0\nfor t in range(N-1):\n    # sinyal: harga NAIK besok?\n    naik_besok = harga[t+1] > harga[t]\n    if LOOKAHEAD:\n        posisi = 1 if naik_besok else -1   # curang: tahu masa depan!\n    else:\n        posisi = 1 if harga[t] > harga[t-1] else -1  # jujur: momentum lampau\n    cuan += posisi*(harga[t+1]-harga[t])/harga[t]\n\nprint(f"Mode: {\'CURANG (lookahead)\' if LOOKAHEAD else \'JUJUR\'}")\nprint(f"Return total: {cuan:.0%}")\nprint()\nprint("Lookahead = ujian dengan kunci jawaban.")\nprint("Audit: \'apakah info ini tersedia SAAT ITU?\'")\n'}, {'heading': 'Walk-Forward Sederhana', 'intro': 'Validasi strategi momentum dengan walk-forward.', 'title': 'Lab 2 — Walk-Forward', 'hint': 'Ubah WINDOW 36 → 12 (train pendek). OOS makin berisik — train butuh cukup data!', 'code': '# Walk-forward: train 36 bln -> test 12 bln, geser\nimport random\nrandom.seed(7)\nWINDOW = 36   # bulan train (ubah!)\nN = 120\nrets = [random.gauss(0.008, 0.04) for _ in range(N)]\n\noos = []\nt = WINDOW\nwhile t + 12 <= N:\n    train = rets[t-WINDOW:t]\n    # \'strategi\': ikut rata-rata train (momentum sederhana)\n    sinyal = 1 if sum(train)/len(train) > 0 else -1\n    hasil = sum(sinyal*r for r in rets[t:t+12])\n    oos.append(hasil)\n    t += 12\n\nimport statistics\nprint(f"OOS per window: {[f\'{x:.0%}\' for x in oos]}")\nprint(f"Rata-rata OOS: {statistics.mean(oos):.1%}")\nprint()\nprint("OOS murni = simulasi penggunaan nyata.")\nprint("Decay (menurun antar window) = edge sekarat.")\n'}], 'decisions': [{'kondisi': 'Sebelum percaya backtest', 'pakai': 'Audit 3 dosa', 'alasan': 'Lookahead/survivor/biaya.', 'contoh': 'Checklist wajib.'}, {'kondisi': 'Banyak trial dicoba', 'pakai': 'Deflated Sharpe', 'alasan': 'Koreksi p-hacking.', 'contoh': '1000 trial → skeptis.'}, {'kondisi': 'Validasi final', 'pakai': 'Walk-forward', 'alasan': 'OOS murni + decay.', 'contoh': '5 window.'}, {'kondisi': 'OOS jauh &lt; IS', 'pakai': 'Tolak / sederhanakan', 'alasan': 'Overfitting.', 'contoh': 'Kurangi parameter.'}], 'rule10': '<ol><li><strong>Audit</strong> 3 dosa dulu.</li><li><strong>OOS wajib</strong>.</li><li><strong>Catat semua</strong> trial.</li><li><strong>Biaya 2x</strong> asumsi.</li></ol>', 'case': {'toc': 'Mini-Case: Sharpe 3,0', 'title': 'Strategi Sempurna yang Hancur', 'body': '<p>Backtest Sharpe 3,0 → live −20% (6 bulan). Sebab: laporan final dipakai 4 bulan lebih awal (lookahead).</p>', 'q': '(a) Mekanisme kegagalan? (b) Bagaimana audit menangkap? (c) Sistem pencegahan?', 'pembahasan': "<p>(a) <strong>Lookahead</strong>: sinyal dari masa depan → Sharpe palsu. Live tanpa 'teropong' = hancur.</p>\n<p>(b) <strong>'Apakah info tersedia saat itu?'</strong> + vintage data → Sharpe 3,0 → 0,4. <strong>Mati di lab.</strong></p>\n<p>(c) <strong>Checklist audit</strong> (PIT/delisted/biaya/OOS) + <strong>jurnal trial</strong> + <strong>walk-forward</strong> + <strong>deflated Sharpe</strong>. Kejujuran = sistem, bukan niat.</p>"}, 'quiz': [{'q': "Strategi pakai laporan final untuk 'trading' 4 bulan sebelumnya. Ini?", 'options': ['OK', 'Lookahead bias — melihat masa depan', 'Alpha', 'Efisien'], 'correct': 1, 'why': 'Benar: info belum tersedia saat itu. Pakai vintage (as-reported) data!'}, {'q': '1000 trial, terbaik Sharpe 2,0. Sikap?', 'options': ['Live!', 'Skeptis: deflated Sharpe (ekspektasi 1,5 dari noise)', 'Tambah leverage', 'Publikasikan'], 'correct': 1, 'why': "Benar: 'terbaik dari 1000' = juara menghafal. DSR mengoreksi jumlah trial."}, {'q': 'IS Sharpe 3,0, OOS 0,3. Diagnosis?', 'options': ['Hebat', 'Overfitting — tolak/sederhanakan', 'Naikkan ukuran', 'Tunggu'], 'correct': 1, 'why': 'Benar: jurang IS→OOS = menghafal noise. Strategi sehat: OOS mendekati IS.'}, {'q': 'Walk-forward OOS: 1,5 → 1,2 → 0,8 → 0,4 → 0,1. Artinya?', 'options': ['Membaik', 'Decay — edge sekarat, jangan live', 'Stabil', 'Acak'], 'correct': 1, 'why': 'Benar: edge terkikis (crowding/regime). Detektor kematian dini bekerja.'}, {'q': 'Asumsi biaya backtest yang aman?', 'options': ['Nol', '2x perkiraan (margin of safety)', 'Setengah', 'Komisi saja'], 'correct': 1, 'why': 'Benar: jika mati dengan biaya 2x = terlalu rapuh. Include impact + slippage!'}], 'rangkum': ['<strong>3 dosa</strong>: lookahead, survivorship, biaya — audit wajib.', '<strong>Overfitting</strong>: IS vs OOS; jurang = menghafal.', '<strong>Walk-forward</strong>: OOS murni + deteksi decay.', '<strong>Deflated Sharpe</strong>: koreksi jumlah trial.', '<strong>Aturan</strong>: jurnal semua trial; biaya 2x; OOS wajib.', '<strong>Prinsip</strong>: backtest jujur = pertanyaan jujur.'], 'prev': ['pm-d3-regresi-faktor', 'PM-D3'], 'next': ['pm-d5-metrik-kinerja', 'PM-D5']}, {'slug': 'pm-d5-metrik-kinerja', 'id': 'PM-D5', 'track': 'Portfolio Management', 'title_html': 'Metrik Kinerja & Risiko:<br/>Sharpe hingga CVaR', 'title_plain': 'Metrik Kinerja: Sharpe, Sortino, Drawdown, VaR/CVaR', 'chapter_summary': 'Metrik analis: Sharpe, Sortino, Calmar, max drawdown & underwater, VaR/CVaR historis, dan kapan tiap metrik berbohong. Lab kalkulator metrik lengkap & VaR/CVaR.', 'tujuan': ['Menghitung Sharpe, Sortino, Calmar.', 'Menjelaskan max drawdown dan recovery.', 'Menghitung VaR & CVaR historis.', 'Menjelaskan kelemahan tiap metrik.'], 'story_title': 'Cerita: Sharpe 2,0 yang Bangkrut', 'story': "<p><strong>Hedge fund</strong>: Sharpe <strong>2,0</strong> (5 tahun)! Investor masuk <strong>Rp50M</strong>. <strong>Sebulan</strong> kemudian: <strong>−40%</strong> — fund <strong>tutup</strong>. Kok bisa? Strategi <strong>jual put</strong> (short vol): untung kecil <em>setiap</em> bulan (Sharpe tinggi!) sampai <strong>ekor</strong> datang — <strong>sekali</strong>, mematikan.</p>\n<p>Twist-nya: <strong>Sharpe buta ekor</strong> — distribusi <em>skew negatif</em> terlihat 'hebat' sampai bencana. <strong>Satu metrik = satu kebohongan.</strong> Lesson ini: panel instrumen lengkap.</p>", 'concepts': [{'id': 'riskadj', 'toc': 'Sharpe, Sortino, Calmar', 'title': 'Risk-Adjusted — Sharpe & Kawan', 'body': '<p><strong>Definisi.</strong> <strong>Sharpe</strong> = (R − R_f)/σ — return per <em>total</em> risiko. <strong>Sortino</strong>: penyebut = <em>downside deviation</em> (hanya risiko buruk!). <strong>Calmar</strong> = return / <strong>max drawdown</strong>.</p>\n<p><strong>Kelemahan</strong>: Sharpe <strong>buta skew</strong> (short-vol terlihat hebat!); Sortino butuh <em>target</em>; Calmar sensitif <em>satu</em> kejadian.</p>', 'formulas': [{'math': 'Sharpe = \\frac{R - R_f}{\\sigma} \\quad;\\quad Sortino = \\frac{R - T}{\\sigma_{down}} \\quad;\\quad Calmar = \\frac{R}{MaxDD}', 'symbols': ['<Tex math={String.raw`\\sigma_{down}`} />: deviasi return di bawah target T saja', 'Sharpe &gt; 1: baik; &gt; 2: luar biasa (curigai skew!)', 'Paket: Sharpe + Sortino + Calmar + skew — jangan satu']}], 'intuisi': 'Metrik seperti <strong>panel dashboard mobil</strong>: Sharpe = <strong>kecepatan</strong>; Sortino = <strong>kecepatan di turunan</strong>; Calmar = <strong>rem terburuk yang pernah</strong>; skew = <strong>lampu oli</strong>. Ngebut (Sharpe 2,0) dengan <strong>lampu oli menyala</strong> (skew −3) = mogok depan mata.', 'kapan': 'Factsheet: tampilkan paket, bukan satu angka.', 'worked': {'title': '📐 Contoh: Bedah short-vol (klik untuk buka)', 'body': '<p>Strategi jual put: Sharpe <strong>2,0</strong>, Sortino <strong>2,5</strong>, skew <strong>−3</strong>, MaxDD historis <strong>5%</strong>.</p>\n<p><strong>Lampu oli</strong>: skew −3 = <strong>ekor kiri</strong>! Calmar = 15%/5% = 3 (terlihat bagus — <em>karena</em> ekor belum datang!).</p>\n<p><strong>Verdict</strong>: <strong>tolak</strong> — Sharpe tinggi + skew sangat negatif = <strong>bom waktu</strong>. Benar saja: −40% sebulan kemudian.</p>'}, 'charts': []}, {'id': 'drawdown', 'toc': 'Drawdown', 'title': 'Drawdown — Luka & Sembuh', 'body': '<p><strong>Definisi.</strong> <strong>Drawdown</strong>: penurunan dari <em>puncak</em> terakhir. <strong>MaxDD</strong>: yang terdalam. <strong>Underwater chart</strong>: visual luka. <strong>Recovery</strong>: waktu kembali ke puncak — <strong>−50% butuh +100%</strong> untuk pulih!</p>\n<p><strong>Psikologi</strong>: MaxDD = <strong>ujian terberat investor</strong> (PM-C6!) — lebih penting dari Sharpe untuk <em>retensi</em>.</p>', 'formulas': [{'math': 'DD_t = \\frac{P_t - \\max_{s \\leq t} P_s}{\\max_{s \\leq t} P_s}', 'symbols': ['Recovery dari −50%: butuh +100% (asimetri brutal!)', 'Dari −20%: butuh +25%', 'Investor kabur di MaxDD → tidak menikmati recovery']}], 'intuisi': 'Drawdown seperti <strong>luka</strong>: MaxDD = <strong>luka terdalam</strong>; underwater = <strong>berapa lama berdarah</strong>; recovery = <strong>penyembuhan</strong>. Luka 50% butuh <strong>obat 100%</strong> (asimetri!). Investor = pasien yang <strong>kabur saat berdarah</strong>.', 'kapan': 'Risk report: MaxDD + underwater selalu tampil.', 'worked': {'title': '📐 Contoh: Matematika brutal (klik untuk buka)', 'body': '<p>Rp100jt → −50% = Rp50jt. Pulih ke 100? Butuh <strong>+100%</strong> (= Rp50jt lagi!).</p>\n<p><strong>−20%</strong> → butuh +25%. <strong>−80%</strong> (gorengan!) → butuh <strong>+400%</strong> (mustahil!).</p>\n<p><strong>Implikasi</strong>: <strong>hindari kerugian besar</strong> &gt; kejar untung besar. Inilah matematika di balik <strong>stop-loss &amp; diversifikasi</strong>. Lindungi downside dulu!</p>'}, 'charts': [{'data': '[{x: ["Jan","Feb","Mar","Apr","Mei","Jun","Jul","Agu"], y: [0,-5,-12,-20,-15,-8,-3,0], type: "scatter", mode: "lines", fill: "tozeroy", marker: {color: "#ef4444"}, line: {width: 2}, name: "drawdown"}]', 'title': 'Underwater chart: drawdown dari puncak (%)', 'layout': '{xaxis: {title: "Bulan"}, yaxis: {title: "Drawdown (%)"}, showlegend: false}', 'cara': 'Area merah = di bawah puncak terakhir. Nol = puncak baru.', 'interpretasi': 'Luka terdalam <strong>−20%</strong> (Apr), sembuh <strong>4 bulan</strong> (Agu). Underwater chart menunjukkan <strong>dua dimensi penderitaan</strong>: <em>dalamnya</em> (MaxDD) &amp; <em>lamanya</em> (recovery). Investor yang kabur di Apr <strong>melewatkan</strong> pemulihan — <strong>komunikasikan ekspektasi</strong> ini di muka (PM-C1!).'}]}, {'id': 'var', 'toc': 'VaR & CVaR', 'title': 'VaR & CVaR — Bahasa Risiko', 'body': "<p><strong>Definisi.</strong> <strong>VaR 95%</strong>: kerugian <em>maksimal</em> di 95% hari 'normal' — <strong>tidak bilang</strong> seberapa parah 5% terburuk! <strong>CVaR/Expected Shortfall</strong>: <em>rata-rata</em> kerugian di 5% terburuk — <strong>jujur tentang ekor</strong>.</p>\n<p><strong>Aturan</strong>: VaR untuk <em>limit harian</em>; CVaR untuk <em>modal &amp; ekor</em>. <strong>Keduanya buta</strong> di luar data historis → <strong>stress test</strong> (PM-D6!).</p>", 'formulas': [{'math': 'VaR_{95\\%} = -Q_{5\\%}(R) \\quad;\\quad CVaR_{95\\%} = -E[R \\mid R < -VaR]', 'symbols': ['<Tex math={String.raw`Q_{5\\%}`} />: persentil 5% return', "VaR: 'tidak lebih buruk dari X di 95% hari'", "CVaR: 'JIKA termasuk 5% terburuk, rata-rata rugi Y'", 'CVaR ≥ VaR selalu (ekor lebih dalam)']}], 'intuisi': "VaR seperti <strong>'banjir maksimal 95% tahun'</strong> — tidak bilang <em>sedalam apa</em> saat 5% banjir besar datang! CVaR = <strong>'rata-rata kedalaman saat banjir besar'</strong>. Warga (investor) butuh <strong>keduanya</strong>: tanggul (VaR) + <strong>evakuasi</strong> (CVaR).", 'kapan': 'Limit trading harian (VaR); alokasi modal & risiko ekor (CVaR).', 'worked': {'title': '📐 Contoh: Angka jujur (klik untuk buka)', 'body': "<p>Portofolio Rp10M. Return harian historis: VaR 95% = <strong>2%</strong> (Rp200jt).</p>\n<p><strong>Artinya</strong>: 95% hari rugi ≤ Rp200jt. <strong>Tidak artinya</strong>: 'rugi maksimal Rp200jt'! (Salah kaprah #1!)</p>\n<p><strong>CVaR 95%</strong> = <strong>3,5%</strong> (Rp350jt) — rata-rata saat 5% terburuk.</p>\n<p><strong>Laporan benar</strong>: 'VaR Rp200jt; CVaR Rp350jt; stress 2008: −Rp2M.' <strong>Tiga angka, tiga cerita.</strong></p>"}, 'charts': []}], 'myths': [{'t': 'Sharpe 2,0 = investasi hebat. Masuk besar.', 'benar': '<strong>Short-vol: Sharpe 2,0 → bangkrut −40%.</strong> Sharpe <strong>buta skew</strong>. Cek: skew? MaxDD? CVaR? <strong>Satu metrik = satu kebohongan.</strong> Paket lengkap atau tidak sama sekali.'}, {'t': 'VaR 95% Rp200jt = kerugian maksimal Rp200jt.', 'benar': "<strong>Salah kaprah #1!</strong> VaR = 'di 95% hari <em>normal</em>'. 5% terburuk <strong>bisa jauh lebih dalam</strong> (itulah CVaR!). VaR tanpa CVaR + stress test = <strong>rasa aman palsu</strong>."}], 'tips': ['<strong>Tampilkan paket 5: Sharpe, skew, MaxDD, CVaR, stress.</strong> Satu halaman risk report. Jika ada yang menolak tampilkan salah satunya — <strong>tanyakan kenapa</strong>.', '<strong>Hafal asimetri recovery.</strong> −10%→+11%, −20%→+25%, −50%→+100%, −80%→+400%. Tulis di dinding. <strong>Pertahanan &gt; serangan.</strong>'], 'labs': [{'heading': 'Kalkulator Metrik Lengkap', 'intro': 'Hitung Sharpe, Sortino, MaxDD, Calmar dari return bulanan.', 'title': 'Lab 1 — Kalkulator Metrik', 'hint': 'Ubah SKEW_CRASH True → False (tanpa crash). Sharpe mirip, MaxDD beda jauh — metrik butuh paket!', 'code': '# Kalkulator metrik: Sharpe, Sortino, MaxDD, Calmar\nimport math, random\nrandom.seed(21)\nSKEW_CRASH = True   # ubah ke False!\nrets = [random.gauss(0.012, 0.03) for _ in range(59)]\nrets.append(-0.40 if SKEW_CRASH else 0.01)\n\nn = len(rets)\nmean = sum(rets)/n\nsd = math.sqrt(sum((r-mean)**2 for r in rets)/(n-1))\ndown = [r for r in rets if r < 0]\ndsd = math.sqrt(sum(r**2 for r in down)/len(down))\nsharpe = mean/sd*math.sqrt(12)\nsortino = mean/dsd*math.sqrt(12)\n# max drawdown\npek, mdd, nav, peak_nav = 1.0, 0.0, 1.0, 1.0\nfor r in rets:\n    nav *= 1+r; pek = max(pek, nav); mdd = min(mdd, nav/pek-1)\ncalmar = (mean*12)/abs(mdd)\n\nprint(f"Sharpe : {sharpe:.2f}   Sortino: {sortino:.2f}")\nprint(f"MaxDD  : {mdd:.0%}   Calmar : {calmar:.2f}")\nprint()\nprint("Crash:", SKEW_CRASH)\nprint("Sharpe mirip, MaxDD beda jauh -> SATU metrik menipu!")\n'}, {'heading': 'Kalkulator VaR & CVaR', 'intro': 'Hitung VaR 95% dan CVaR historis dari return harian.', 'title': 'Lab 2 — Kalkulator VaR/CVaR', 'hint': 'Ubah NILAI 10000 → 50000 (Rp jt). VaR/CVaR skala linear — risiko proporsional!', 'code': '# VaR & CVaR historis\nimport random\nrandom.seed(33)\nNILAI = 10000   # Rp jt (ubah!)\nrets = sorted([random.gauss(0.0005, 0.015) for _ in range(1000)])\n\nidx = int(0.05*1000)\nvar = -rets[idx]\nekor = rets[:idx]\ncvar = -sum(ekor)/len(ekor)\n\nprint(f"VaR 95% : {var:.2%} = Rp{var*NILAI:.0f}jt")\nprint(f"CVaR 95%: {cvar:.2%} = Rp{cvar*NILAI:.0f}jt")\nprint()\nprint("VaR: 95% hari rugi <= ini. BUKAN rugi maksimal!")\nprint("CVaR: rata-rata rugi di 5% hari terburuk.")\nprint("Keduanya buta di luar histori -> tambah STRESS TEST.")\n'}], 'decisions': [{'kondisi': 'Factsheet / evaluasi', 'pakai': 'Paket 5 metrik', 'alasan': 'Satu metrik menipu.', 'contoh': 'Sharpe+skew+MaxDD+CVaR+stress.'}, {'kondisi': 'Limit harian trading', 'pakai': 'VaR 95%', 'alasan': 'Operasional.', 'contoh': 'Desk limit.'}, {'kondisi': 'Alokasi modal / ekor', 'pakai': 'CVaR + stress test', 'alasan': 'Jujur tentang bencana.', 'contoh': 'PM-D6.'}, {'kondisi': 'Retensi investor', 'pakai': 'Komunikasikan MaxDD ekspektasi', 'alasan': 'Psikologi &gt; matematika.', 'contoh': 'IPS (PM-C1).'}], 'rule10': '<ol><li><strong>Paket</strong>, bukan satu metrik.</li><li><strong>Skew</strong> selalu dicek.</li><li><strong>CVaR</strong> &gt; VaR untuk ekor.</li><li><strong>Stress</strong> melengkapi histori.</li></ol>', 'case': {'toc': 'Mini-Case: Sharpe 2,0', 'title': 'Hedge Fund yang Bangkrut', 'body': '<p>Sharpe 2,0 (5 tahun) → −40% sebulan → tutup. Strategi: short-vol (skew −3).</p>', 'q': '(a) Mengapa Sharpe menipu? (b) Metrik apa yang menangkap? (c) Sistem due diligence?', 'pembahasan': "<p>(a) <strong>Sharpe buta skew</strong>: untung kecil rutin (σ kecil!) + ekor kiri fatal. Short-vol = <strong>mengumpulkan receh di rel kereta</strong>.</p>\n<p>(b) <strong>Skew −3</strong> (lampu oli!) + <strong>CVaR</strong> + <strong>stress test</strong> ('bagaimana jika vol meledak 3x?').</p>\n<p>(c) <strong>Paket 5 wajib</strong> + <strong>wawancara strategi</strong> ('dari mana return berasal?') + <strong>batas skew</strong> di IPS.</p>"}, 'quiz': [{'q': 'Sharpe 2,0, skew −3. Verdict?', 'options': ['Hebat', 'Bahaya: bom waktu short-vol — tolak', 'Lumayan', 'Masuk'], 'correct': 1, 'why': 'Benar: Sharpe buta ekor. Skew −3 = lampu oli menyala. Cek CVaR + stress!'}, {'q': 'VaR 95% Rp200jt artinya?', 'options': ['Rugi maksimal Rp200jt', '95% hari normal rugi ≤ Rp200jt (5% bisa lebih dalam!)', 'Untung minimal', 'Tidak ada arti'], 'correct': 1, 'why': 'Benar: salah kaprah #1 = baca VaR sebagai maksimal. Itulah gunanya CVaR.'}, {'q': 'Portofolio −50%. Butuh berapa untuk pulih?', 'options': ['+50%', '+100%', '+25%', '+200%'], 'correct': 1, 'why': 'Benar: asimetri brutal. −80% → +400% (mustahil). Hindari rugi besar!'}, {'q': 'Sortino vs Sharpe: bedanya?', 'options': ['Sama', 'Sortino: penyebut downside deviation (risiko buruk saja)', 'Sortino lebih kecil', 'Tidak ada'], 'correct': 1, 'why': "Benar: volatilitas ke atas bukan 'risiko'. Sortino menghukum yang benar."}, {'q': 'Paket risk report minimal?', 'options': ['Sharpe saja', 'Sharpe + skew + MaxDD + CVaR + stress', 'Return saja', 'VaR saja'], 'correct': 1, 'why': 'Benar: satu metrik = satu kebohongan. Lima = panel dashboard lengkap.'}], 'rangkum': ['<strong>Sharpe</strong>: return/σ; <strong>buta skew</strong>.', '<strong>Sortino</strong>: downside deviation; <strong>Calmar</strong>: return/MaxDD.', '<strong>Drawdown</strong>: MaxDD + underwater + asimetri recovery.', '<strong>VaR</strong>: 95% normal; <strong>CVaR</strong>: rata-rata 5% terburuk.', '<strong>Paket 5</strong>: Sharpe, skew, MaxDD, CVaR, stress.', '<strong>Aturan</strong>: satu metrik menipu; pertahanan &gt; serangan.'], 'prev': ['pm-d4-backtesting', 'PM-D4'], 'next': ['pm-d6-risk-reporting', 'PM-D6']}, {'slug': 'pm-d6-risk-reporting', 'id': 'PM-D6', 'track': 'Portfolio Management', 'title_html': 'Risk Reporting:<br/>Dashboard & Komunikasi', 'title_plain': 'Risk Reporting: Limit, Stress Test, Komunikasi Risiko', 'chapter_summary': 'Capstone toolkit: dashboard limit monitoring (utilization, breach), stress test & skenario, dan komunikasi risiko ke dewan — bahasa bisnis, bukan Yunani. Lab monitor limit & stress test. Lesson terakhir Track 7.', 'tujuan': ['Merancang dashboard limit monitoring.', 'Menjalankan stress test skenario.', 'Menghitung limit utilization & breach.', 'Mengomunikasikan risiko dalam bahasa bisnis.'], 'story_title': 'Cerita: Laporan yang Menyelamatkan Rapat Dewan', 'story': "<p><strong>Mar 2020</strong>: risk manager membawa <strong>40 halaman</strong> Yunani (VaR, Greeks, kovarians) ke dewan. Direksi <strong>tertidur</strong>. <strong>Apr 2020</strong>: ia kembali dengan <strong>1 halaman</strong>: <em>'Jika pasar −30%: kita rugi RpX. Limit: 2 breach. Aksi: ...'</em> Direksi <strong>langsung putuskan</strong> tambah lindung nilai.</p>\n<p>Twist-nya: <strong>angka yang sama, nasib berbeda</strong> — karena <strong>komunikasi</strong>. Laporan risiko terbaik yang <strong>tidak dibaca</strong> = tidak ada laporan. <strong>Risk reporting = penerjemahan</strong>: Yunani → keputusan. Lesson penutup: dari angka ke aksi.</p>", 'concepts': [{'id': 'dashboard', 'toc': 'Dashboard Limit', 'title': 'Dashboard — Panel Pilot', 'body': '<p><strong>Definisi.</strong> <strong>Limit</strong>: batas risiko (VaR, eksposur, konsentrasi). <strong>Utilization</strong> = aktual/limit. <strong>Breach</strong>: &gt; 100% → <strong>eskalasi</strong>! <strong>Traffic light</strong>: hijau (&lt; 80%), kuning (80–100%), merah (breach).</p>\n<p><strong>Aturan</strong>: dashboard <strong>harian</strong> untuk trading; <strong>mingguan/bulanan</strong> untuk dewan. <strong>1 halaman eksekutif</strong> + lampiran detail.</p>', 'formulas': [], 'intuisi': 'Dashboard seperti <strong>panel pilot</strong>: pilot tidak baca <em>manual mesin</em> saat turbulensi — ia lihat <strong>lampu</strong> (hijau/kuning/merah) + <strong>1 angka</strong> kunci. Risk dashboard = <strong>lampu + angka</strong>, bukan ensiklopedia.', 'kapan': 'Monitoring harian (desk); laporan berkala (dewan).', 'worked': {'title': '📐 Contoh: Pagi yang merah (klik untuk buka)', 'body': '<p>Dashboard Senin: VaR utilization <strong>95%</strong> (kuning), konsentrasi single-name <strong>105%</strong> (MERAH — breach!).</p>\n<p><strong>Eskalasi</strong>: desk kurangi 10% sebelum siang (aturan tertulis!). <strong>Selasa</strong>: 88% (kuning).</p>\n<p><strong>Tanpa dashboard</strong>: breach ketahuan <strong>saat rugi</strong>. Dengan dashboard: <strong>sebelum</strong>. <strong>Monitoring = pencegahan.</strong></p>'}, 'charts': [{'data': '[{x: ["VaR", "Konsentrasi", "Durasi", "FX"], y: [95, 105, 70, 45], type: "bar", marker: {color: ["#e8a838","#ef4444","#16a34a","#16a34a"]}, text: ["95%","105% BREACH","70%","45%"], textposition: "outside"}]', 'title': 'Limit utilization dashboard (%)', 'layout': '{xaxis: {title: "Limit"}, yaxis: {title: "Utilisasi (%)"}, showlegend: false, shapes: [{type: "line", x0: -0.5, x1: 3.5, y0: 100, y1: 100, line: {color: "#ef4444", dash: "dash"}}]}', 'cara': 'Tinggi batang = utilisasi vs limit (garis merah putus-putus = 100%). Warna = traffic light.', 'interpretasi': '<strong>Merah</strong> (konsentrasi 105%) = breach → <strong>aksi hari ini</strong>. <strong>Kuning</strong> (VaR 95%) = waspada → <strong>siapkan rencana</strong>. <strong>Hijau</strong> = aman. Dewan membaca ini <strong>10 detik</strong> — itulah tujuannya: <strong>keputusan cepat</strong>, bukan kekaguman.'}]}, {'id': 'stress', 'toc': 'Stress Test', 'title': 'Stress Test — Simulasi Bencana', 'body': "<p><strong>Definisi.</strong> <strong>Stress test</strong>: 'bagaimana jika...?' — <strong>historis</strong> (2008, 2020, 1998!) + <strong>hipotetis</strong> (rate +3%, rupiah −20%, <em>keduanya</em>!). <strong>Reverse stress</strong>: 'skenario apa yang <em>membunuh</em> kita?'</p>\n<p><strong>Aturan</strong>: stress <strong>bukan prediksi</strong> — melainkan <strong>uji ketahanan</strong>. Lapor: skenario → rugi → <strong>aksi</strong>.</p>", 'formulas': [{'math': '\\text{Rugi}_{skenario} = \\sum w_i \\times shock_i', 'symbols': ['Shock: historis (2008: saham −50%) atau hipotetis', 'Reverse: cari shock yang bikin rugi = modal!', 'Output: angka + AKSI (bukan angka saja)']}], 'intuisi': 'Stress test seperti <strong>latihan kebakaran</strong>: bukan <em>ramalan</em> kebakaran — tapi memastikan <strong>pintu darurat</strong> (likuiditas, lindung nilai) <em>bisa dibuka</em>. Gedung tanpa latihan = <strong>panik saat api</strong> (Mar 2020!).', 'kapan': 'Kuartalan (dewan); sebelum event besar (pemilu, The Fed).', 'worked': {'title': '📐 Contoh: Skenario 2020 (klik untuk buka)', 'body': "<p>Portofolio Rp10M (60/40). <strong>Skenario</strong>: saham −30%, obligasi +5% (flight to quality).</p>\n<p><strong>Rugi</strong> = 0,6×(−30%) + 0,4×5% = <strong>−16%</strong> = Rp1,6M.</p>\n<p><strong>Reverse</strong>: 'rugi Rp3M (30%) butuh saham <strong>−55%</strong>.' <strong>Aksi</strong>: collar jika probabilitas naik (PM-C9!).</p>\n<p><strong>Dewan</strong>: 'Rp1,6M bisa ditahan? Ya.' → <strong>tidur nyenyak</strong>. Itulah <em>value</em> stress test.</p>"}, 'charts': []}, {'id': 'komunikasi', 'toc': 'Komunikasi', 'title': 'Komunikasi — Yunani ke Keputusan', 'body': "<p><strong>Definisi.</strong> <strong>Aturan 1 halaman</strong>: <em>so what?</em> di paragraf 1. <strong>Bahasa bisnis</strong>: 'rugi RpX jika...' bukan 'VaR 95%...'. <strong>Struktur</strong>: temuan → dampak → <strong>opsi aksi</strong> → rekomendasi.</p>\n<p><strong>Prinsip</strong>: dewan membayar <strong>keputusan</strong>, bukan <strong>kuliah</strong>. Jika mereka tidak bertindak = <strong>laporan gagal</strong> (bukan mereka bodoh!).</p>", 'formulas': [], 'intuisi': "Komunikasi risiko seperti <strong>penerjemah</strong>: dokter (risk manager) bilang 'miokard infark' → pasien (dewan) dengar <strong>'serangan jantung, perlu operasi <em>sekarang</em>'</strong>. Istilah latin = <strong>gagal menerjemahkan</strong> = pasien mati (keputusan telat).", 'kapan': 'Setiap laporan ke non-teknis: dewan, klien, regulator.', 'worked': {'title': '📐 Contoh: 40 halaman → 1 (klik untuk buka)', 'body': "<p><strong>Buruk</strong> (40 hlm): 'VaR 95% Rp200jt, CVaR Rp350jt, beta 1,1, Greeks...' → dewan <strong>tertidur</strong>.</p>\n<p><strong>Baik</strong> (1 hlm): 'Jika pasar −30% (seperti Mar 2020): <strong>rugi Rp1,6M</strong>. 2 limit breach. <strong>Opsi</strong>: (a) collar Rp50jt, (b) kurangi 10%. <strong>Rekomendasi: (a)</strong>.'</p>\n<p><strong>Hasil</strong>: keputusan <strong>15 menit</strong>. <strong>So what dulu, Yunani kemudian</strong> (di lampiran).</p>"}, 'charts': []}], 'myths': [{'t': 'Laporan risiko makin tebal = makin bagus.', 'benar': '<strong>40 halaman = dewan tertidur = keputusan nol.</strong> Tebal = <em>malas menyintesis</em>. <strong>1 halaman eksekutif</strong> (so what + opsi + rekomendasi) + lampiran. <strong>Diukur dari keputusan</strong>, bukan halaman.'}, {'t': 'Tugas risk manager = menghitung angka. Komunikasi urusan lain.', 'benar': '<strong>Angka tak terbaca = tidak ada.</strong> Penerjemahan (Yunani → keputusan) = <em>inti</em> pekerjaan. Quant hebat yang tak bisa menjelaskan = <strong>asisten yang mahal</strong>. Belajar menulis = <strong>promosi</strong>.'}], 'tips': ["<strong>Tulis 'so what' dulu, baru angka.</strong> Sebelum kirim laporan: baca paragraf 1 — jika tidak ada implikasi aksi, <strong>tulis ulang</strong>. Kebiasaan ini = karir.", '<strong>Automasi dashboard, manualkan insight.</strong> Angka = otomatis (harian). <strong>Interpretasi</strong> = manusia (mingguan). Jangan bayar analis mahal untuk <em>copy-paste</em> angka.'], 'labs': [{'heading': 'Monitor Limit', 'intro': 'Bangun traffic-light monitor dari data utilisasi.', 'title': 'Lab 1 — Monitor Limit', 'hint': 'Ubah KONSENTRASI 1.05 → 0.75 (di bawah limit). Lampu hijau — aksi selesai!', 'code': '# Monitor limit: traffic light\nLIMITS = {"VaR": 0.95, "Konsentrasi": 1.05, "Durasi": 0.70, "FX": 0.45}  # ubah!\n\nprint(f"{\'limit\':<14}{\'util\':>7}  status")\nfor nama, u in LIMITS.items():\n    if u > 1.0: status = "MERAH (breach!)"\n    elif u > 0.8: status = "KUNING (waspada)"\n    else: status = "HIJAU (aman)"\n    print(f"{nama:<14}{u:>6.0%}  {status}")\n\nbreach = [k for k, v in LIMITS.items() if v > 1.0]\nprint()\nif breach:\n    print(f"AKSI: kurangi {\', \'.join(breach)} HARI INI (aturan eskalasi).")\nelse:\n    print("Semua aman. Kuning = siapkan rencana.")\n'}, {'heading': 'Stress Test Sederhana', 'intro': 'Hitung rugi portofolio di beberapa skenario.', 'title': 'Lab 2 — Stress Test', 'hint': 'Ubah SHOCK_SAHAM -0.30 → -0.50 (2008!). Rugi membesar — uji ketahanan!', 'code': '# Stress test: skenario -> rugi\nW_SAHAM, W_OBLIGASI = 0.6, 0.4\nNILAI = 10_000  # Rp jt\nSHOCK_SAHAM = -0.30   # ubah!\nSHOCK_OBL = 0.05\n\nrugi = W_SAHAM*SHOCK_SAHAM + W_OBLIGASI*SHOCK_OBL\nprint(f"Skenario: saham {SHOCK_SAHAM:.0%}, obligasi {SHOCK_OBL:+.0%}")\nprint(f"Rugi portofolio: {rugi:.1%} = Rp{rugi*NILAI:,.0f}jt")\nprint()\n# reverse stress: shock saham agar rugi 30%?\ntarget = -0.30\ns_rev = (target - W_OBLIGASI*SHOCK_OBL)/W_SAHAM\nprint(f"Reverse: rugi 30% butuh saham {s_rev:.0%}")\nprint("Lapor: skenario -> rugi -> AKSI (bukan angka saja).")\n'}], 'decisions': [{'kondisi': 'Monitoring harian', 'pakai': 'Dashboard traffic-light otomatis', 'alasan': 'Pencegahan &gt; kuratif.', 'contoh': 'Desk trading.'}, {'kondisi': 'Breach limit', 'pakai': 'Eskalasi tertulis, aksi hari itu', 'alasan': 'Aturan &gt; diskusi.', 'contoh': 'Kurangi 10%.'}, {'kondisi': 'Laporan dewan', 'pakai': '1 halaman: so what + opsi + rekomendasi', 'alasan': 'Keputusan cepat.', 'contoh': 'Kuartalan.'}, {'kondisi': 'Event besar dekat', 'pakai': 'Stress test ad-hoc', 'alasan': 'Uji ketahanan.', 'contoh': 'Pre-pemilu.'}], 'rule10': '<ol><li><strong>1 halaman</strong> eksekutif.</li><li><strong>So what</strong> dulu.</li><li><strong>Opsi + rekomendasi</strong>.</li><li><strong>Bahasa bisnis</strong>.</li></ol>', 'case': {'toc': 'Mini-Case: 40 Halaman', 'title': 'Laporan yang Menyelamatkan Rapat', 'body': '<p>Mar 2020: 40 halaman Yunani → dewan tertidur. Apr: 1 halaman (skenario + rugi + aksi) → keputusan 15 menit.</p>', 'q': '(a) Apa bedanya? (b) Struktur 1 halaman? (c) Ukuran keberhasilan laporan?', 'pembahasan': '<p>(a) <strong>Penerjemahan</strong>: sama-sama angka; yang kedua <strong>so-what + opsi + rekomendasi</strong> dalam bahasa bisnis.</p>\n<p>(b) <strong>Temuan → dampak (Rp!) → opsi aksi → rekomendasi.</strong> Yunani di lampiran.</p>\n<p>(c) <strong>Keputusan yang diambil.</strong> Bukan halaman, bukan kekaguman. Laporan tanpa aksi = gagal.</p>'}, 'quiz': [{'q': 'Konsentrasi 105% dari limit. Status & aksi?', 'options': ['Hijau, biarkan', 'MERAH breach — kurangi hari ini (eskalasi)', 'Kuning, tunggu', 'Naikkan limit'], 'correct': 1, 'why': 'Benar: &gt;100% = breach = aturan eskalasi tertulis. Monitoring = pencegahan.'}, {'q': 'Aturan 1 halaman eksekutif?', 'options': ['Yunani lengkap', 'So what + dampak Rp + opsi + rekomendasi', 'Grafik saja', 'Copy data'], 'correct': 1, 'why': 'Benar: dewan membayar keputusan, bukan kuliah. Diukur dari aksi.'}, {'q': 'Reverse stress test menanyakan?', 'options': ['Prediksi krisis', 'Skenario apa yang membunuh kita?', 'Return ekspektasi', 'Biaya'], 'correct': 1, 'why': 'Benar: bukan prediksi — uji ketahanan. Cari shock yang bikin rugi = modal.'}, {'q': 'VaR 95% (kuning). Tindakan?', 'options': ['Panik', 'Siapkan rencana (belum breach)', 'Abaikan', 'Tutup desk'], 'correct': 1, 'why': 'Benar: kuning = waspada. Rencana siap sebelum merah. Traffic light = bahasa cepat.'}, {'q': 'Ukuran laporan risiko berhasil?', 'options': ['Tebal', 'Keputusan yang diambil', 'Banyak grafik', 'Cepat selesai'], 'correct': 1, 'why': 'Benar: laporan tanpa aksi = gagal. So what dulu, Yunani di lampiran.'}], 'rangkum': ['<strong>Dashboard</strong>: limit + utilization + traffic light; 1 halaman eksekutif.', '<strong>Breach</strong>: eskalasi tertulis, aksi hari itu.', '<strong>Stress</strong>: historis + hipotetis + reverse; skenario → rugi → aksi.', '<strong>Komunikasi</strong>: bahasa bisnis; so what dulu.', '<strong>Automasi</strong>: angka otomatis, insight manusia.', '<strong>Track 7 selesai</strong>: dari IPS hingga keputusan — analis portofolio siap.'], 'prev': ['pm-d5-metrik-kinerja', 'PM-D5'], 'next': ['/', 'Daftar Materi']}]
